const canvas=document.querySelector('#flowers'),ctx=canvas.getContext('2d'),slider=document.querySelector('#color'),play=document.querySelector('#play'),label=document.querySelector('#play-label'),icon=document.querySelector('#play-icon'),hint=document.querySelector('#hint');
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
let progress=0,playing=!reduced.matches,ready=false,previous=0,elapsed=0;
const yellow=document.createElement('canvas'),pink=document.createElement('canvas'),layer=document.createElement('canvas');
function setPlaying(value){playing=value;label.textContent=value?'Pausar':'Continuar';icon.textContent=value?'Ⅱ':'▷';play.setAttribute('aria-label',value?'Pausar transformación':'Continuar transformación');}
function render(){if(!ready)return;const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.drawImage(yellow,0,0);if(progress>0){const lc=layer.getContext('2d');lc.clearRect(0,0,w,h);lc.globalCompositeOperation='source-over';lc.drawImage(pink,0,0);lc.globalCompositeOperation='destination-in';const boundary=progress*(w+w*.7)-w*.35,fade=w*.35;const gradient=lc.createLinearGradient(boundary-fade,0,boundary+fade,0);gradient.addColorStop(0,'rgba(0,0,0,1)');gradient.addColorStop(1,'rgba(0,0,0,0)');lc.fillStyle=gradient;lc.fillRect(0,0,w,h);ctx.drawImage(layer,0,0);}slider.value=String(Math.round(progress*100));slider.setAttribute('aria-valuetext',`${Math.round(progress*100)} % rosado`);const a=[237,205,118],b=[236,159,189];document.querySelector('h1 em').style.color=`rgb(${a.map((v,i)=>Math.round(v+(b[i]-v)*progress)).join(',')})`;hint.textContent=progress>=1?'El cariño se queda':playing?'Deja que florezca':'A tu ritmo';}
const image=new Image();image.onload=()=>{const w=Math.min(1200,image.naturalWidth),h=Math.round(w*image.naturalHeight/image.naturalWidth);for(const c of [canvas,yellow,pink,layer]){c.width=w;c.height=h;}const yc=yellow.getContext('2d');yc.drawImage(image,0,0,w,h);const pixels=yc.getImageData(0,0,w,h),d=pixels.data;for(let i=0;i<d.length;i+=4){const r=d[i]/255,g=d[i+1]/255,b=d[i+2]/255;const mask=Math.min(1,Math.max(0,(r-g*.94)*12))*Math.min(1,Math.max(0,(g-b-.035)*7));if(mask>0){const lum=Math.max(r,g,b);d[i]=255*(r*(1-mask)+Math.min(1,lum*1.04)*mask);d[i+1]=255*(g*(1-mask)+lum*.52*mask);d[i+2]=255*(b*(1-mask)+lum*.73*mask);}}pink.getContext('2d').putImageData(pixels,0,0);ready=true;document.querySelector('#loading').hidden=true;render();};image.onerror=()=>{document.querySelector('#loading').textContent='No pudimos cargar las flores. Recarga la página para volver a intentarlo.';setPlaying(false);};image.src='flowers.png';
slider.addEventListener('input',()=>{setPlaying(false);progress=Number(slider.value)/100;elapsed=progress*14000+1500;render();});play.addEventListener('click',()=>{if(progress>=1){progress=0;elapsed=0;}setPlaying(!playing);render();});document.querySelector('#restart').addEventListener('click',()=>{progress=0;elapsed=0;setPlaying(!reduced.matches);render();});reduced.addEventListener('change',e=>{if(e.matches)setPlaying(false);});document.addEventListener('visibilitychange',()=>{previous=0;});function animate(time){const dt=previous?Math.min(time-previous,60):0;previous=time;if(ready&&playing&&!document.hidden){elapsed+=dt;progress=Math.max(0,Math.min(1,(elapsed-1500)/14000));if(progress===1)setPlaying(false);render();}requestAnimationFrame(animate);}setPlaying(playing);requestAnimationFrame(animate);
